private void checkClass(JavaContext context, UClass node) {
    if (node.isInterface() || PsiModifier.STATIC in node) return;
    PsiClass containing = node.getContainingClass();
    if (containing == null) return; // top-level
    JavaEvaluator evaluator = context.getEvaluator();
    if (!evaluator.extendsClass(node, ANDROID_OS_HANDLER, false)) return;
    boolean reported = false;
    UMethod[] constructors = node.getConstructors();
    if (constructors.length == 0) {
        report(context, node);
        return;
    }
    for (UMethod ctor : constructors) {
        UCallExpression superCall = findSuperCall(ctor, node);
        if (superCall == null) {
            report(context, node);
            return;
        }
        if (isDefaultOrMainLooper(superCall)) {
            report(context, node);
            return;
        }
    }
}
```
