private UCallExpression findSuperCall(UMethod method, UClass cls) {
    UExpression body = method.getUastBody();
    if (body == null) return null;
    UCallExpression[] result = new UCallExpression[1];
    body.accept(new AbstractUastVisitor() {
        @Override public boolean visitCallExpression(@NotNull UCallExpression node) {
            if (node.getKind() == UastCallKind.CONSTRUCTOR_CALL) {
                PsiMethod resolved = node.resolve();
                if (resolved != null && resolved.isConstructor()) {
                    PsiClass containing = resolved.getContainingClass();
                    PsiClass superClass = cls.getSuperClass();
                    if (containing != null && superClass != null && containing.equals(superClass)) {
                        result[0] = node;
                        return true;
                    }
                }
            }
            return super.visitCallExpression(node);
        }
    });
    return result[0];
}
```
