private boolean isDefaultOrMainLooper(JavaContext context, UCallExpression call) {
    PsiMethod method = call.resolve();
    if (method == null || !method.isConstructor()) {
        // Fallback: no args means default Handler()
        return call.getValueArgumentCount() == 0;
    }
    PsiParameter[] params = method.getParameterList().getParameters();
    List<UExpression> args = call.getValueArguments();
    for (int i = 0; i < params.length; i++) {
        PsiType paramType = params[i].getType();
        String canonical = paramType.getCanonicalText();
        if (ANDROID_OS_LOOPER.equals(canonical)) {
            UExpression arg = i < args.size() ? args.get(i) : null;
            return arg == null || isMainLooperReference(context, arg);
        }
    }
    // No Looper parameter -> Handler() or Handler(Callback): uses current thread looper.
    return true;
}
```
