private boolean isMainLooperReference(JavaContext context, UExpression expr) {
    if (!(expr instanceof UCallExpression)) return false;
    PsiMethod method = ((UCallExpression) expr).resolve();
    if (method == null) return false;
    return "getMainLooper".equals(method.getName())
        && context.getEvaluator().isMemberInClass(method, ANDROID_OS_LOOPER);
}
