@Override
public List<String> applicableSuperClasses() {
    return Collections.singletonList(ANDROID_OS_HANDLER);
}

@Override
public void visitClass(JavaContext context, UClass declaration) {
    checkHandlerClass(context, declaration);
}

private void checkHandlerClass(JavaContext context, UClass node) {
    // Skip static and top-level
    if (node.hasModifierProperty(PsiModifier.STATIC)) return;
    if (node.getContainingClass() == null) return;

    // For anonymous classes, check parent constructor call
    if (node instanceof UAnonymousClass) {
        UCallExpression parentCall = UastUtils.getParentOfType(node, UCallExpression.class, false);
        if (parentCall != null && isDefaultOrMainLooper(context, parentCall)) {
            report(context, node, parentCall);
        }
        return;
    }

    // Named inner class
    // Check constructors
    UMethod[] constructors = node.getConstructors();
    if (constructors.length == 0) {
        report(context, node, null);
        return;
    }

    for (UMethod constructor : constructors) {
        // Check for super(...) call with looper, or this(...) call
        UCallExpression superCall = findSuperCall(constructor, node);
        if (superCall != null) {
            if (isDefaultOrMainLooper(context, superCall)) {
                report(context, node, null);
                return;
            }
            continue;
        }

        if (hasThisCall(constructor, node)) {
            continue;
        }

        report(context, node, null);
        return;
    }
}
```

